def fib(n: int) -> int:
    """
    Compute the n-th Fibonacci number using the fast doubling method.
    Time complexity: O(log n)
    Space complexity: O(log n)
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    def fib_pair(k: int) -> tuple[int, int]:
        """
        Returns a tuple (F(k), F(k+1)) using fast doubling.
        """
        if k == 0:
            return (0, 1)
        a, b = fib_pair(k >> 1)
        c = a * (2 * b - a)  # F(2k)
        d = a * a + b * b   # F(2k+1)
        return (c, d + c)  # F(2k+2) = d + F(2k+1)

    return fib_pair(n)[1]
